    (3039,'First ionisation energy across Period 3','B','["Because atomic radius increases","Because nuclear charge increases while shielding stays roughly similar","Because the number of electron shells increases","Because the outer electron is farther from the nucleus"]'::jsonb),
    (3046,'Large jump in successive ionisation energies','B','["Na","Mg","Al","Si"]'::jsonb)
  )
  select count(*) into v_bad
  from expected e
  left join public.questions q on q.id=e.question_id
  where q.id is null
     or q.subject_id<>4
     or q.is_active is not true
     or q.quality_status<>'published'
     or q.topic<>'Electrons in atoms'
     or q.subtopic<>e.subtopic
     or lower(coalesce(q.qtype,''))<>'mcq'
     or upper(trim(coalesce(q.correct_answer,'')))<>e.correct_answer
