  if v_bad<>0 then
    raise exception 'AI-4 Chemistry Electrons diagnostic batch refused: one or more target questions changed';
  end if;

  if exists (
    select 1 from public.question_answer_diagnostics
    where question_id in (1908,1917,1927,1931,1937,1939,1941,1945,1953,1956,1960,1962,1968,1971,3036,3037,3039,3046)
      and quality_status='published'
  ) then
